import { chromium } from 'playwright-core'

const BASE = process.env.BASE_URL || 'http://127.0.0.1:8098'
const logs = []
const PNG =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=='

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('console', (m) => logs.push(`[console:${m.type()}] ${m.text()}`))
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`))

try {
  await page.goto(BASE, { waitUntil: 'load', timeout: 60000 })
  await page.waitForFunction(() => !!window.__VUE_APP_STORE__, null, { timeout: 30000 })

  await page.evaluate((url) => {
    window.__VUE_APP_STORE__.dispatch('preview/openPreview', {
      urlList: [url],
      nameList: ['test.png'],
      currentIndex: 0,
    })
  }, PNG)
  await page.waitForSelector('.custom-image-viewer .el-dialog__headerbtn', { timeout: 10000 })

  // instrument: count clicks on the close button + mousedown on header
  await page.evaluate(() => {
    window.__diag = { click: 0, mousedownHeader: 0, mousedownTargetIsClose: 0 }
    document.addEventListener(
      'click',
      (e) => {
        if (e.target.closest && e.target.closest('.el-dialog__headerbtn')) window.__diag.click++
      },
      true
    )
    const header = document.querySelector('.custom-image-viewer .el-dialog__header')
    if (header) {
      header.addEventListener('mousedown', (e) => {
        window.__diag.mousedownHeader++
        if (e.target.closest && e.target.closest('.el-dialog__headerbtn'))
          window.__diag.mousedownTargetIsClose++
      })
    }
  })

  const posBefore = await page.evaluate(() => {
    const d = document.querySelector('.custom-image-viewer')
    return d ? d.style.position : 'NO_DIALOG'
  })

  await page.click('.custom-image-viewer .el-dialog__headerbtn')
  await page.waitForTimeout(1000)

  const after = await page.evaluate(() => window.__VUE_APP_STORE__.getters.showViewer)
  const diag = await page.evaluate(() => window.__diag)
  const posAfter = await page.evaluate(() => {
    const d = document.querySelector('.custom-image-viewer')
    return d ? d.style.position : 'NO_DIALOG'
  })
  const wrapperAfter = await page.evaluate(
    () => document.querySelectorAll('.custom-image-viewer').length
  )

  console.log(
    JSON.stringify(
      { base: BASE, after, wrapperAfter, posBefore, posAfter, diag, closed: !after && wrapperAfter === 0, logs: logs.slice(-15) },
      null,
      2
    )
  )
} catch (e) {
  console.log(JSON.stringify({ error: String(e), logs: logs.slice(-15) }, null, 2))
} finally {
  await browser.close()
}
